export const kitBlurbs: Record<string, string> = {
  "activity-feed": "A running log of what just happened in a product, such as releases, security warnings and API calls, laid out as compact cards that people can filter, search and open to see the raw data behind each one. New entries slide in at the top as they arrive. It suits status pages, developer consoles, admin dashboards and any back office where people need to see recent system activity at a glance.",
  "activity-heatmap": "A contribution-style calendar that shows at a glance which days were busy and which were quiet, with a second view that shows the hours of the week when activity peaks. Visitors can point at any square to see the exact figure. It works for habit trackers, team dashboards, developer profiles, booking or order volume, and any product that wants to show consistency over time.",
  "ai-agent-activity": "Shows the work behind an AI answer as a step-by-step trail: what the assistant searched, which tools it called, what came back and how long each step took. Steps change from waiting to running to done, and people can open any step to read its inputs and outputs. It suits AI products, coding assistants, automation tools and anywhere users need to trust what an agent did.",
  "ai-response": "The answer bubble for an AI assistant, built for text that arrives a piece at a time. It shows a thinking state, fills in formatted text, code and tables as they come, and finishes with sources and quick actions to copy, retry or rate the answer. Links from the model are checked before they become clickable. It fits chat products, help centres, AI search pages and any app that shows generated answers.",
  "alert": "Inline banners for messages that matter on a page: something worked, something needs attention, something failed. Each carries an icon and a short explanation, can hold an action button and folds away cleanly when closed, so nothing jumps. They're useful in account settings, checkout and billing pages, forms, dashboards and onboarding flows.",
  "badge": "Compact labels for statuses, counts and tags: a live indicator that pulses quietly, a notification count that rolls to its new value, and tags people can remove with a tap. It's a small building block that makes navigation menus, product cards, data tables, filters, inboxes and settings screens clearer without pulling focus away from the content.",
  "bar-chart": "A clear, readable bar chart for comparing a few categories over time, with one switch to see them side by side or stacked into totals. Visitors can point at any period for exact figures and turn series on and off from the legend. It fits analytics dashboards, usage and billing pages, internal reports and any product page that needs to show growth.",
  "batch-gesture-tray": "A selection pattern for lists: tick a few items and a floating bar appears with what you can do to all of them at once, then moves out of the way when you're done. It's handy for file managers, inboxes, admin tables, media libraries and order lists, anywhere people need to archive, export or delete several things together.",
  "chat": "A complete chat screen for an AI assistant or support bot, with past conversations on the side, a readable message thread that handles code, and a message box that supports attachments and keyboard shortcuts. On phones it tucks the history away behind a menu. It's a ready starting point for AI products, customer support widgets, internal tools and help desks.",
  "donut-chart": "Shows how a whole breaks into parts, such as spend by service, traffic by channel or storage by type, as a ring with the total in the middle or as a half-circle gauge. Pointing at a slice brings up its exact amount and share, and the legend lets visitors hide slices to compare the rest. It fits billing pages, analytics cards and finance or budgeting apps.",
  "faq": "The classic questions-and-answers block, made easier to scan. Visitors can search or filter by topic instead of scrolling, and answers open in place without leaving the page. It works on pricing pages, product and support pages, onboarding docs, and restaurant or shop sites, anywhere common questions should be answered before someone gets in touch.",
  "funnel-chart": "Makes it obvious where people leave a sign-up or checkout flow. Each step narrows with the number of people who reach it, and the gaps between steps show how many were lost. A summary line calls out the overall conversion and the weakest step. It fits growth dashboards, marketing reports, sales pipelines and onboarding analytics.",
  "interactive-area-chart": "A single-metric chart for the number people care about most, such as a balance, revenue or users, with quick range buttons and a crosshair that reads out any day. Switching ranges reshapes the line instead of reloading it, so the change reads as one continuous movement. It makes a strong centrepiece for finance apps, account overviews, analytics dashboards and investor pages.",
  "live-line-chart": "A live readout for numbers that change every second, such as traffic, sales, sensor readings or queue length, with the line drifting steadily across rather than jumping. Visitors can hover to pause and look back over the last minute. It fits operations dashboards, status pages, trading or IoT screens and product launch counters.",
  "loader": "A small set of calm loading indicators (a spinner, dots, a progress sweep and a ripple) that share one size and colour setting, so the same waiting state looks right in a button, a card or a full page. Use it wherever content or results take a moment: forms, search, dashboards, checkout and app start-up.",
  "morphing-shape-loader": "A playful loading mark that keeps changing shape instead of spinning, which makes waiting feel a little less mechanical. It works as a page or splash loader, a placeholder while generated content arrives, or a brand moment in creative portfolios, AI tools and design-led apps, and it can be tinted or filled to match any palette.",
  "not-found": "A dead-end page that still feels cared for: a big glowing number half hidden behind a frosted folder, gently floating and shifting in depth as the cursor moves, with a clear headline and a way back home. Drop it in as the catch-all route of a product site, documentation portal or web app so a broken link becomes a small moment of polish instead of a bare error.",
  "notification-bell": "The familiar bell in a product's top bar, done with care: a crisp red count, a little wobble when something new comes in, and a dropdown that lists what happened with clear unread markers and one-tap clearing. Fits dashboards, admin panels, SaaS headers and any app that needs to tell people quietly that something changed while they were away.",
  "notification-stack": "A compact pile of recent alerts that takes the space of one card but holds many: newer messages land on top, old ones can be flicked away sideways, and the whole pile can be fanned out to review. Useful for activity panels, deploy and build status, inboxes in dashboards and any app that has to show several short updates without flooding the screen.",
  "orbital-loading-ring": "A small loader with more character than a spinning circle: two satellites orbit in opposite directions around a softly glowing core. It reads as calm, technical and alive, which suits sync and upload states, AI or data-processing screens, splash moments and any dark interface that wants its waiting moments to look intentional.",
  "payment-receipt-printer": "A checkout confirmation that feels physical: a little counter-top printer hums and pushes out a paper receipt with torn edges, line items, total and barcode, then lets the customer copy the order number. A warm, memorable way to close a purchase on shop, restaurant ordering and booking sites, or to dress up an order-history screen.",
  "payment-status": "The screen people see right after paying, covering every outcome: in progress, being verified, done, declined or refunded. The success view gives a reassuring tick, the amount and the key details, with a receipt that can be opened or saved; the failure view offers a clear retry. Fits checkouts, subscriptions, donations and in-app purchases.",
  "product-tour": "A guided first-run walkthrough that dims the screen and shines a light on one part of the interface at a time, with a short note beside it and simple next and back controls. Ideal for onboarding new users to a dashboard or web app, announcing a new feature, or walking customers through a setup flow without writing a separate help page.",
  "recovery-ledger": "A clear history of every saved state — what changed, who changed it and when — with the live version marked and older ones a click away from a detailed diff and a one-tap rollback. Suited to deploy dashboards, document and design editors, settings with audit trails and any admin tool where people need confidence that a change can be undone.",
  "rocket-party-popper": "A playful finish line: a tiny rocket lifts off and a shower of confetti follows, turning a completed step into a small celebration. Great for launch and publish buttons, onboarding milestones, finished checklists, first sales or any moment in a product where users deserve a little reward without leaving the page.",
  "skeleton": "Calm placeholder shapes that hold the layout while data arrives, with a soft light passing over them so the page never looks frozen, then a gentle hand-off to the real content. A staple for feeds, profile cards, dashboards, product lists and any screen that loads from the network and should feel fast even while waiting.",
  "smooth-accordion": "A tidy question-and-answer list that keeps long pages short: tap a question and the answer opens with an unhurried, physical motion while the previous one folds away. Works for FAQ sections, pricing details, product specifications, shipping and returns policies, settings groups and help centres, on both marketing sites and the inside of web apps.",
  "stack-unfold-panel": "A set of numbered cards that open one at a time to reveal more detail, with the rest of the stack shifting politely out of the way. Great for feature breakdowns, step-by-step processes, plan comparisons, technical specs and onboarding checklists — anywhere a page has several topics that each deserve a short explanation.",
  "stat-card": "Headline numbers for a dashboard that reward a closer look: each card shows a key metric, how it moved against the last period in green or red, and a small trend line you can glide across to read any single day. Fits analytics overviews, admin home screens, SaaS reports and investor or sales dashboards on both desktop and mobile.",
  "undo-toast": "The safety net after a destructive action: a quiet message confirms what just happened and offers a few seconds to take it back, with a shrinking line showing how long is left. A good fit for archiving, deleting, moving or sending in email clients, project tools, file managers, admin panels and any app that prefers forgiveness over confirmation dialogs.",
  "unfold-accordion": "A question-and-answer list where opening an item feels like a single, considered gesture: the arrow turns, the panel grows and the answer settles into place together. Made for FAQ sections, pricing and policy pages, help centres, course outlines and product detail pages that want a light, readable structure without visual noise or anything flashy.",
  "velocity-toast": "A short confirmation that pops up from the edge of the screen, says what just happened and leaves on its own, with a thin line showing how long it will stay. Hovering holds it in place so nobody misses the message. Suited to uploads, saves, sent messages, copied links and other quick success or warning notices in any web app.",
  "advanced-data-table": "A complete table for admin screens and dashboards: search, filter chips, sortable columns, multi-select with bulk actions, expandable detail rows and paging, all in one quiet dark panel. On phones it turns itself into a stack of readable cards. Use it for order lists, user directories, inventories or any back-office record view where people need to find, compare and act on many rows at once.",
  "animated-file-upload": "A drag-and-drop uploader that tells people exactly what is happening: the target reacts as a file hovers over it, each file gets its own card with live progress, and finished or rejected files are clearly marked with a way to retry or remove them. A good fit for profile and document uploads, support forms, media libraries and any app step where users hand over files.",
  "calendar": "A month calendar that keeps your eye on the date: pages slide in the direction you move, and the highlight glides to whatever day you pick instead of blinking there. It handles single days and ranges, blocked dates and full keyboard use. Drop it into booking flows, scheduling panels, report filters or any sidebar that needs a quiet, always-visible date picker.",
  "combobox": "A dropdown you can type into: open it, start typing, and the list narrows instantly while a single highlight glides to the best match. Ideal when a plain select would be too long to scroll — choosing a country, a project, a team member, a category or a product variant — in forms, settings pages and filters where speed matters more than browsing.",
  "date-picker": "A form-field date picker that opens a small calendar right where you are typing, lets the selection settle visibly, then tucks itself away and fills in the date. It comes in single-date and range versions, so it covers check-in and check-out, delivery slots, report periods, event dates and any filter that needs a start and an end.",
  "draw-checkbox": "A checkbox that writes its own tick, giving each click a small, satisfying moment of confirmation. It suits places where ticking something should feel deliberate: to-do lists, onboarding checklists, consent and preference panels, or settings with a few clear choices. Includes a mixed state for parent items that are only partly selected.",
  "form": "A matching set of form building blocks — labels, inputs, selects, checkboxes, switches, radios and inline errors — that share one look and one gentle motion. Use it to build settings pages, sign-up and checkout steps, project configuration screens or admin panels quickly, with every control already styled to sit together on a dark interface.",
  "lock-input": "A text field that answers the moment you click into it: its frame visibly tightens around the box, so people always know where they are typing. Works anywhere precision matters — login and sign-up, checkout details, account settings, search bars in dashboards — and shows errors in the same language with a red frame and a message underneath.",
  "otp-input": "A verification-code field split into individual boxes, so people can see exactly how many digits are left and which one they are on. Each keystroke gives a small bounce, and pasting the whole code works in one go. Use it for two-factor sign-in, phone or email verification, payment confirmation and PIN entry screens.",
  "spring-select": "A dropdown with a bit of physical character: the arrow swings open and the list drops into place, so the change of state is easy to follow without being loud. Built for short lists of choices — switching workspace, team or plan, picking a sort order, setting a status — in settings screens, toolbars and forms.",
  "stretch-switch": "A settings toggle with a tactile touch: the knob gives way under your finger and then springs across, so flipping an option feels like pressing something real. It pairs a clear title and short explanation with each switch, making it a natural fit for preference lists, notification settings, privacy controls and feature toggles in apps and dashboards.",
  "airport-matrix-clock": "A world clock that borrows the look of an airport departures board: times and city names are spelled in glowing dot characters, and hovering a row makes its letters flip over in a quick ripple. Visitors can add or remove cities themselves. It suits team pages that show where colleagues are, travel and booking sites, or any dashboard that needs several time zones at a glance.",
  "animated-number": "A counter whose digits roll like the reels of a mechanical meter whenever the value changes, so visitors feel the number moving rather than just see it replaced. It is ideal for revenue tiles, live sales or donation totals, pricing toggles and stat sections on a landing page — anywhere a figure updates and you want the change itself to be noticed.",
  "car-smoke-page-transition": "A cinematic page transition: a red sports car drifts across the screen in a cloud of tyre smoke, and the page fades out behind it just as the next view loads. It turns an ordinary link into a moment of theatre, perfect for automotive brands, racing or gaming sites, product launches and playful portfolios that want visitors to remember how they moved between pages.",
  "circular-orbit": "A hero gallery where a ring of photos slowly circles a single bold word, with the pictures on one side growing large and sharp while the far side shrinks into the background. Hovering lets visitors pause it to look closer. It works well as the opening of a portfolio, a studio or agency homepage, an event recap or a brand page that wants to show many images without a grid.",
  "cursor-follower": "A soft ring that trails the visitor's mouse around the page with a slight springy lag and swells while it moves. It adds a tactile, crafted feel without hiding the real cursor, and can carry a small label or icon. Use it on creative portfolios, studio sites, interactive landing pages and showcases where you want the whole page to feel responsive to the hand.",
  "density-lens": "A magnifying glass that follows the visitor's mouse over a busy card or diagram, enlarging whatever sits beneath it without changing the layout. It lets a dense infographic, technical drawing, product detail shot or data panel stay compact on the page while still letting curious visitors read the fine print up close.",
  "dependency-trace": "A compact relationship map that lights up the connections of whatever node the visitor points at and fades out the rest, so a tangle of lines becomes one clear path. It suits architecture diagrams in technical documentation, product pages explaining how services or features fit together, onboarding flows and any small network that needs to be explored rather than read.",
  "depth-corridor": "A stack of cards that recedes into the screen like a hallway, with the chosen card sharp in front and the rest fading and blurring into the distance. Visitors step through it by clicking or with the arrow keys. It suits feature tours, layered architecture explanations, release timelines, process steps and portfolio case studies that benefit from a sense of depth.",
  "dot-field": "A fine, evenly spaced dot pattern washed with a soft colour gradient, made to sit quietly behind headlines, pricing cards or app screenshots. It adds texture and a hint of brand colour to empty space without competing with the content, and stays crisp on every screen. A dependable backdrop for landing pages, dashboards and section dividers.",
  "dot-shader": "A living dot-grid backdrop that gently ripples on its own and reacts to the visitor's pointer, pushing dots aside and lighting them in your accent colour. It gives a hero section, product launch page or developer tool homepage a sense of technology and responsiveness while leaving plenty of calm space for a headline on top.",
  "evil-eye": "A hand-drawn blue glass amulet that hangs from a cord and swings with believable weight as the visitor's pointer passes by, then sways back to rest. It brings a moment of charm and craft to jewellery and gift shops, Mediterranean restaurants and travel brands, wellness and spiritual sites, or any landing page that wants a memorable, tactile mascot.",
  "expandable-data-row": "A data table whose rows open up in place to reveal the full story behind each entry — account details, recent activity and quick actions — without sending the visitor to another page. It keeps admin panels, CRM lists, order histories and member directories scannable at a glance while still giving every record room to breathe when someone wants more.",
  "focus-mode": "A way to spotlight one card on a busy dashboard: pick a card and it lifts forward while everything else fades back, then return to the full view with a single click or the Escape key. Helpful for analytics pages, live presentations of results, report summaries and any overview where people need to concentrate on one number at a time.",
  "glitch-text": "Display type that breaks up like a damaged screen — colours split apart, slices slide sideways or the letters scramble before resolving — then snaps back to clean text. It can loop, react to hover or fire on click. A strong fit for gaming and esports sites, tech launches, music and event posters, cyber-themed portfolios and error pages with personality.",
  "glyph-matrix": "A curtain of glowing characters raining down a dark panel, with bright leading glyphs and fading trails that ripple faster wherever the visitor's pointer passes. It instantly sets a hacker, sci-fi or terminal mood, perfect behind a hero headline for developer tools, security products, game launches, hackathons and tech event pages.",
  "gravity-particle-burst": "A button that celebrates being pressed: a little shower of sparks bursts from the exact spot the visitor touched and tumbles away under gravity. It turns key moments — publishing, completing a purchase, finishing onboarding, claiming a reward — into a small reward of their own, without needing a full confetti screen.",
  "interactive-timeline": "A step-by-step progress timeline that shows what is done, what is running right now and what comes next, with each step opening up to reveal its details and numbers. It fits deployment and order tracking, project roadmaps, onboarding checklists, changelogs, delivery updates and case studies that tell a story in stages.",
  "mac-os-folder-cards": "A friendly desktop-style folder that lifts and lets its cards peek out when the visitor hovers, then opens into a tidy grid of everything inside. It turns a plain list of features, projects, documents or resources into something people want to open — great for portfolios, product feature sections, resource libraries and team or service overviews.",
  "meteors": "A quiet shower of shooting stars that streak across a card or section, each leaving a fading tail of light. It adds atmosphere to dark-themed feature cards, pricing highlights, launch announcements, space and astronomy sites, or night-time event pages, giving the background gentle life without pulling attention from the words on top.",
  "metric-hud": "A compact monitoring panel that pairs headline numbers with a live-feeling trend line, lets visitors switch time ranges and scrub along the chart to read exact values. It fits status pages, SaaS dashboards, investor or impact reports and any product page that wants to show performance with credibility rather than just a big number.",
  "money-card": "A friendly wallet card that shows a balance, favourite contacts and the latest payment, and lets people send or request money through a polished keypad sheet that confirms with a satisfying check. It is a ready reference for fintech and banking apps, peer-to-peer payments, loyalty and gift-card wallets, or a convincing product mock-up on a landing page.",
  "morphing-blob": "A soft, glowing shape of violet and cyan that constantly reshapes itself like a living liquid and drifts gently toward the visitor's mouse. It makes an eye-catching but calm backdrop for a hero headline, an AI or wellness product, a music or creative studio site, or any section that needs a splash of colour and quiet movement.",
  "morphing-icon": "A small icon swap where the old symbol spins out and the new one spins in, giving toggles a clear before-and-after. It suits save, mute, play, lock and theme switches in toolbars, media players and cards — anywhere a button flips between two states and the user should notice that it did.",
  "nimbu-mirchi": "A hanging good-luck charm of chillies and a lemon that swings toward your cursor and sways back with real weight. It is a playful hero or footer ornament for food, festival and culture sites, a launch page that wants a little personality, or a page-not-found screen — decoration that rewards curiosity without asking anything of the visitor.",
  "package-box": "An unboxing moment: a cardboard parcel that opens its flaps and lifts a packing slip up to the reader. It fits order confirmations, thank-you pages after checkout, shipping notifications, gift reveals and onboarding screens that hand over a welcome note — places where a small sense of occasion makes the message land.",
  "particle-delete": "A delete action that turns a list row into drifting dust before the list closes up, so removing something feels final but not abrupt. It suits dashboards, file and resource managers, notification centres and to-do lists — anywhere people clear items one at a time and benefit from a clear, satisfying confirmation that the item is gone.",
  "photo-box": "A keepsake box of instant photos that slides open when you approach and lets you pull one print out to look at it closely. It works as a small gallery for a portfolio, a travel or wedding page, an “about us” section with a few personal moments, or a product page showing three highlights in a warmer, tactile way.",
  "pricing": "A two-plan pricing block that sets a free option beside a highlighted paid one, with a single glint on the upgrade button to draw the eye. It drops into SaaS landing pages, app and template stores, course sites and membership pages — anywhere the choice is simple and the paid tier should stand out without shouting.",
  "profile-card": "A bold, dark profile card with a glowing blue cover, an avatar that overlaps the edge and the essentials — name, bio, follower numbers, link and a follow button. It suits creator pages, team and speaker sections, community member directories and link-in-bio pages where one person should be introduced at a glance.",
  "rainbow-button": "A dark call-to-action button framed by a moving band of rainbow light that also glows softly beneath it. It works as the single headline action on a launch page, an upgrade or “get access” prompt, or a sign-up button on a dark hero — one per screen, where colour is meant to pull focus.",
  "reveal-card": "A dark card that tilts toward your cursor with a soft sheen and reveals an extra line or two of detail while you hover. It suits feature grids, service or plan cards, project tiles and status panels, where the headline should stay clean and the supporting facts appear only for visitors who show interest.",
  "scrollvelocitytext": "A headline that stretches apart and dissolves as the reader scrolls on, then gathers itself back as they scroll up. It gives a long landing page, a manifesto section, a portfolio intro or a chapter break a sense of momentum, turning a plain scroll into a small moment of motion without adding any controls.",
  "shooting-stars": "A living night sky of twinkling stars with meteors that streak across it every few seconds and can be launched with a click. It makes an atmospheric backdrop for a dark hero, an event or launch countdown, a sign-up screen or a wish-making moment, while the headline in front stays perfectly readable.",
  "sparkles-core": "A soft field of twinkling specks and tiny stars that drift behind your content and scatter away from the cursor. It suits dark hero sections, launch and waitlist pages, celebratory or festive moments, and product reveals where a quiet sense of magic should sit behind the headline rather than compete with it.",
  "speed-warp": "A warp-speed star field that sends streaks of light rushing past the viewer. It gives instant energy to a launch or countdown page, a loading or “preparing your space” screen, a game or sci-fi landing, or a section about speed and performance — best behind a short, bold line of text.",
  "spotlight-card": "A dark card that glows wherever the cursor rests, as if a small torch were passing over it. It suits feature grids, pricing tiles, integration lists, team profiles and dashboard panels on dark sites, adding a quiet sense of responsiveness and depth without moving the layout or distracting from the content itself.",
  "stacked-cards": "A scroll-driven stack of large story cards that pile up like a deck as the reader moves down the page, each new chapter settling on top of the last. It works well for annual reviews, case studies, product feature tours and blog highlights — sequences of a few big ideas that deserve a full card each.",
  "sticky-pages": "Full sections that pin in place and let the next one slide over them like sheets of paper, leaving a thin edge of each behind. It suits step-by-step product stories, process or methodology pages, menus of services and onboarding tours — any narrative where each chapter should briefly own the screen before handing over.",
  "story-card": "A looping row of photo stories where one is open and the next ones peek in from the side, ready to expand with a click, swipe or scroll. It suits news and blog highlights, case-study reels, travel or event galleries and product launches — a compact way to show several features while keeping one in focus.",
  "text-scramble-decoder": "A line of text that scrambles into random characters and then decodes itself letter by letter, like a terminal locking onto a signal. It suits status messages, confirmation labels, hero taglines on technical products, security and developer-tool pages, and small “connected” or “synced” indicators that deserve a moment of attention.",
  "thinking-orb": "A small living sphere of light that breathes, spins and stirs in different moods, made to show that an assistant is listening, thinking or composing. It fits AI chat interfaces, voice assistants, loading and processing states, and avatar spots in apps — a calmer, more expressive replacement for a spinner.",
  "torque-dial": "A tactile rotary knob you twist with the mouse or a finger, which keeps spinning briefly when flicked and settles on its own. It suits audio and media apps, smart-home and lighting controls, creative tools and settings panels — anywhere a value is adjusted by feel rather than typed in.",
  "wallet-balance": "A green wallet pouch with a few account cards that tuck themselves away and mask every amount at the tap of an eye. It fits finance and budgeting apps, payment dashboards, banking home screens and freelancer payout pages — anywhere people want their balances glanceable but private when someone is looking over their shoulder.",
  "wallet-card": "A dark wallet card with a glowing blue panel that catches a soft light as the cursor moves across it, showing a balance and a single action. It suits fintech landing pages, checkout and top-up screens, account overviews and loyalty or gift-card balances, where one number and one button should feel tangible.",
  "animated-tabs": "A segmented tab bar where the highlight behind the current tab physically slides to the one you pick, stretching to fit its label, while the content below hands over with a short rise. It suits settings pages, product sections and documentation where a few views share one spot, and it keeps the switch readable instead of letting panels pop in and out.",
  "branching-submenu": "A compact two-level navigation card: the main sections sit in a column on the left and the chosen section's sub-pages unfold in a panel beside it, like branches off a trunk. It fits dashboards, settings and developer tools where people need to see one layer deeper without opening a full page, and it works from the keyboard as well as the mouse.",
  "breadcrumb": "A breadcrumb trail that stays short on deep pages by folding the middle of the path away, then opens it in place when someone wants it. A soft highlight follows the pointer from step to step so it is always clear which page a click will lead to. A good fit for documentation, file browsers, shops with nested categories and admin consoles.",
  "dynamic-island": "A tiny floating capsule that opens into a personal card: tap it to say hello, open a short profile with availability status, or jump to contact links — all inside one shape that stretches and rounds into each view. Made for portfolios, freelancer sites and creator pages that want contact details always one tap away without a sidebar or footer block.",
  "expandable-search": "A search box that stays small in a crowded header and opens up the moment someone reaches for it, giving room to type and then tucking itself away when it is left empty. It suits toolbars, documentation headers and app top bars where search should always be visible but should not take space from navigation when nobody is using it.",
  "floating-action-dock": "A floating launcher of app-style icons that swell under the pointer and ease back as it moves on, so the row feels alive without getting in the way. It works as a quick-action bar at the bottom of a web app, a tool palette in an editor, or a playful shortcut strip on a portfolio or product landing page.",
  "glass-navbar": "A floating, see-through header for a product or studio site: logo, a handful of section links and one clear call-to-action. A soft highlight follows the pointer across the links and settles back on the current page, and on phones the whole thing folds into a tidy drop-down menu. A dependable top bar for landing pages, SaaS sites and portfolios.",
  "gooey-menu": "A single-choice dropdown that behaves like a drop of ink: the list drips out of the button, stretches, then breaks free, and gets drawn back in when you choose. It brings personality to a simple menu on a portfolio, studio or event site, or a language and section picker in a playful app, while still working fully from the keyboard.",
  "hamburger-menu": "The familiar three-line menu icon, but it folds cleanly into a close mark and back instead of swapping pictures, so people see that the same button will close what it opened. Drop it into any mobile header, side drawer trigger or compact toolbar; it is accessible out of the box and can be recoloured and resized to match the surrounding bar.",
  "ios-search-bar": "A rounded search field in the style of a phone's native search bar: it waits quietly at a modest width, opens up when tapped, offers a one-touch clear button, and settles back once it is empty. Use it in app headers, list and table filters, help centres and mobile-first web apps where search is frequent but space is tight.",
  "morphing-mega-menu": "A top-level menu for sites with a lot to show: instead of separate dropdowns popping in and out, one panel glides between sections and reshapes itself to fit each one, with a small pointer that tracks the cursor. It suits product companies, platforms and agencies with rich navigation — features, developer resources, company pages — and stays usable by keyboard and touch.",
  "pill-navigation": "A two-tier navigation made of rounded pills: main sections across the top, and for sections that need it, a smaller row of sub-pages that appears right underneath. Both rows show the current choice with a highlight that slides rather than jumps. It fits documentation, product tours, design-system sites and dashboards where a section has a handful of close siblings.",
  "scroll-progress-nav": "A compact table of contents that rides along with a long page, showing how far the reader has got and which chapter they are in, and letting them jump straight to any section. It is a natural fit for long-form articles, case studies, documentation, pricing and feature pages, or any single-page site split into numbered parts.",
  "sidebar": "A full app sidebar that can shrink to an icon rail when people want more room and opens as a swipeable drawer on phones. Grouped links, nested pages, counts and tooltips are all built in, and the highlight glides between items. It is a ready base for dashboards, admin panels, inboxes, project tools and any web app with more than a few destinations.",
  "slide-pagination": "A page-number strip for lists and archives in which the highlight slides to the page you choose, so the jump is easy to follow, while long ranges stay short thanks to ellipses. It fits blog archives, search results, product grids and data tables — anywhere a long list is split into pages and people move back and forth through them.",
  "small-floating-dock": "A pocket-sized row of shortcut buttons that floats over the page, staying slightly tucked until the pointer reaches it and showing unread counts at a glance. It suits quick actions in web apps — compose, search, notifications, help — or a persistent shortcut bar on a mobile-style site, and it can step out of the way while people scroll down.",
  "smart-comparison": "A pricing comparison that helps people decide instead of scroll: plan cards on top, grouped features below, a search box to find the one capability they care about, and a switch that hides everything the plans have in common. It belongs on SaaS pricing pages, product tier pages and any offer with several packages to compare, and it adapts to a one-plan-at-a-time view on phones.",
  "stepper": "A step-by-step progress tracker for multi-part flows that shows where someone is, what is done and what is left, with the progress line filling and checks drawing themselves as they advance. It works for sign-up and onboarding, checkout, setup wizards and long forms broken into stages, and lets people click back to an earlier step to change something.",
  "avatar-stack": "A compact way to say “these people are here”: overlapping profile photos that tuck into one row, with a counter for everyone who does not fit. Pointing at a face lifts it out of the pile and shows the name. Fits project cards, shared documents, team pages, event attendee lists and anywhere a list of collaborators would take too much room.",
  "command-menu": "A keyboard launcher for people who would rather type than click: one shortcut opens a search box over the page, and every page, document and action of the product is a few letters away. Fits documentation sites, dashboards, admin tools and design-heavy portfolios that want power users to move around without hunting through menus.",
  "directional-tooltip": "A small helper label that explains an icon or button the moment someone pauses on it, and appears to slide out of the control it describes so the eye knows which button it belongs to. Works with the keyboard as well as the mouse. Fits toolbars, icon-only navigation, editors and settings screens where space for text labels is tight.",
  "intro-loader": "An opening moment for a website or app: a warm greeting that cycles through several languages before the real page appears, with a thin line showing how far along it is. Visitors can skip it at any time. Fits international brands, portfolios, product launches and landing pages that want a short, human first impression instead of a spinner.",
  "morphing-dialog": "A focused detail view for settings, records or explanations: the page dims and blurs behind a single card, and its heading, subheading and body arrive one after another so the eye reads them in order. Closing is quick by key, button or click outside. Fits dashboards, settings areas and product pages that need to show more without leaving the page.",
  "origin-dropdown": "A small action menu that unfolds from the edge of the button that opened it, so it always feels attached to its trigger whether it opens below, above or to the side. Dangerous actions stand out in red. Fits account menus, row actions in tables, toolbars and any place that needs a few choices tucked behind one button.",
  "peek-card": "A quick look without leaving the page: hovering a reference to an order, invoice or user shows a compact summary card right next to it, with the key facts and a one-tap copy action. Moving into the card keeps it open, and touch screens open it with a tap. Fits admin panels, activity feeds, tables and support tools full of IDs.",
  "selection-basket": "An action bar that appears only when it is useful: as soon as someone ticks items in a list, it rises from the bottom with the count and the things they can do to all of them at once, and disappears when nothing is selected. Fits file managers, inboxes, admin tables, photo galleries and any list where people act on many rows together.",
  "settle-modal": "A confirmation dialog with a sense of weight: the panel lands and settles rather than simply fading in, and its words follow a moment later, which draws attention to the decision being asked for. Fits destructive or important confirmations, short forms, onboarding prompts and any moment where a product needs a clear yes or no.",
  "sheet": "A side panel for editing or inspecting something without leaving the page: it slides in over the content, keeps keyboard focus inside while open, and on phones can be swiped away with a thumb. It can also come from the top or bottom. Fits settings forms, filters, shopping carts, record details and mobile navigation menus.",
  "spotlight-search": "A calm, distraction-free search box that floats over the page: just a field and a list of matching titles, with a soft highlight that slides to whichever result is chosen. Fully usable from the keyboard. Fits documentation sites, component libraries, knowledge bases and apps where people know what they are looking for and want to get there fast.",
  "book-call-button": "A bold, oversized booking button where a bright green capsule sweeps across a black pill and a ringing phone appears as soon as the visitor shows interest. It turns a plain “contact us” moment into a small reward, and suits agency sites, consultancy landing pages, sales demos and any page whose single goal is getting someone onto a call.",
  "button": "The everyday button kit that every other screen leans on: a solid main action, quieter secondary and outline options, a ghost for toolbars, and clearly coloured buttons for deleting or confirming. Each one gives a small physical press, and a built-in loading state covers form submits and saves, so a product can stay consistent from settings pages to checkout.",
  "code-snippet-deck": "A code window for documentation and developer landing pages that shows the same call in several languages, lets readers flip between them, and fills in their own settings before they copy. It turns a static example into something a visitor can adapt on the spot, which suits API docs, SDK quick-starts, integration guides and product pages aimed at engineers.",
  "drag-to-confirm": "A safety catch for irreversible actions: instead of a single click, the visitor drags a handle across a track and the control turns red or green to confirm it is done. It makes deleting data, sending money, unlocking something sensitive or pushing a release feel deliberate, and fits admin panels, banking flows, checkout steps and mobile-first apps.",
  "liquid-ripple-button": "A button that looks partly filled with water: gentle waves roll along its lower half, the level rises when the pointer arrives, and every click sends rings across the surface from the exact spot pressed. It gives a calm, tactile character to sync, refresh or generate actions, and suits water, wellness, weather or cleaning brands and playful product pages.",
  "morphing-button": "A save or submit button that tells the visitor what is happening without a separate message: it shows progress while working, then a clear success or failure right where they clicked. It reduces uncertainty in settings pages, forms, editors and dashboards, anywhere an action takes a moment and people need to know whether it worked.",
  "neon-edge-button": "A dark button outlined by a single bright streak that travels around its edge, quietly drawing the eye without colour or noise. It suits developer tools, deploy and launch actions, dark-themed landing pages and any interface that wants one primary action to feel live while the rest of the screen stays calm.",
  "press-button": "A button that responds to a press like a soft physical key, flattening slightly under the finger and popping back when released. That small bit of weight makes save, cancel and confirm actions feel answered, and it drops into forms, dialogs, toolbars and mobile web apps without changing how the button looks at rest.",
  "split-button": "One button for the action people take most, with a small arrow beside it for the close alternatives: deploy now or to a test environment, save or publish, delete or archive. It keeps a toolbar uncluttered while the extra choices stay one click away, and fits dashboards, editors, publishing tools and admin panels.",
  "typewriter-button": "A button that types its own label back out when pressed, complete with a blinking cursor and optional key clicks, like a command being entered at a terminal. It gives install commands, copy-to-run snippets and developer-tool calls to action a bit of character, and suits docs sites, CLI product pages and retro or hacker-themed designs.",
  "login": "A ready-made sign-in screen for dark interfaces: a short greeting, quick single sign-on options, email and password with clear inline error messages, and a remember-me choice. It covers the whole returning-user moment for SaaS dashboards, member areas, developer tools and internal apps, and pairs naturally with a matching sign-up card.",
  "sign-up": "A complete account-creation card for dark interfaces with name, email, password and confirmation, quick single sign-on options, a terms agreement and a live password-strength meter that coaches people toward a safer choice. It is the natural first step for SaaS trials, membership sites, communities and developer platforms, alongside a matching sign-in card."
};
